    private void racing(){ControllerConfig c=pad.config.copy();LinearLayout b=box();Switch integrated=toggle(b,"Steering + gas / brake",c.integrated),preserve=toggle(b,"Preserve LS vertical output",c.preserveY),hide=toggle(b,"Hide separate LT / RT",c.hideTriggers);text(b,"Up accelerates (RT), down brakes (LT). With vertical output off, LS Y stays centered.");EditText dead=number(b,"Trigger activation dead zone (0–0.5)",c.triggerDeadzone),sensitivity=number(b,"Trigger sensitivity (0.25–3)",c.triggerSensitivity);String[] curves={"LINEAR","SOFT","AGGRESSIVE"};Spinner curve=choice(b,"Trigger curve",new String[]{"Linear","Soft · precise near center","Aggressive"},curves,c.curve);form("Left stick gas / brake",b,()->{c.integrated=integrated.isChecked();c.preserveY=preserve.isChecked();c.hideTriggers=hide.isChecked();c.triggerDeadzone=value(dead,0,.5f);c.triggerSensitivity=value(sensitivity,.25f,3);c.curve=curves[curve.getSelectedItemPosition()];commit(c);});}
