        ControllerConfig c=pad.config.copy();LinearLayout b=box();Switch enabled=toggle(b,"Enable gyro-assisted RS",c.gyroEnabled),aim=toggle(b,"Only while LT is active",c.gyroAimOnly),ix=toggle(b,"Invert horizontal",c.gyroInvertX),iy=toggle(b,"Invert vertical",c.gyroInvertY);
