        EditText gain=number(b,"Sensitivity (0.05–5)",c.gyroSensitivity),smoothing=number(b,"Filtering (0–0.95)",c.gyroSmoothing),dead=number(b,"Rest dead zone (0–0.2 rad/s)",c.gyroDeadzone);
        Button calibrate=new Button(context);calibrate.setText("Calibrate on return to controller");b.addView(calibrate);calibrate.setOnClickListener(v->{pad.gyro.calibrate();Toast.makeText(context,"Enable gyro and keep the phone still for one second after closing Settings.",Toast.LENGTH_LONG).show();});
