        String[] modes={"HOLD","TOGGLE"};Spinner mode=choice(b,"Aim activation",modes,modes,c.aimMode);
        EditText x=number(b,"Camera X sensitivity (0.1–5)",c.cameraX),y=number(b,"Camera Y sensitivity (0.1–5)",c.cameraY),curve=number(b,"Camera response exponent (0.25–3)",c.cameraCurve),smooth=number(b,"Camera smoothing (0–0.95)",c.cameraSmoothing),precision=number(b,"RS sensitivity while LT active (0.1–1)",c.aimSensitivity);
