    private void feedback(){menu("Touch feedback",new String[]{"Off","Light","Medium","Strong"},i->pad.mutate(()->pad.config.haptics=i));}
    private void editorSettings(){ControllerConfig c=pad.config.copy();LinearLayout b=box();String[] names={"XBOX","PLAYSTATION"};Spinner label=choice(b,"Button labels",new String[]{"Xbox","PlayStation"},names,c.labels);Switch grid=toggle(b,"Show grid",c.grid),snap=toggle(b,"Snap positions to grid",c.snap);EditText size=number(b,"Grid spacing (% of width)",c.gridSize*100);form("Labels & editor",b,()->{c.labels=names[label.getSelectedItemPosition()];c.grid=grid.isChecked();c.snap=snap.isChecked();c.gridSize=value(size,1,10)/100;commit(c);});}
