        if(section==0){EditText x=number(b,"Horizontal center (%)",c.x*100),y=number(b,"Vertical center (%)",c.y*100),w=number(b,"Width (%)",c.w*100),h=number(b,"Height (%)",c.h*100);form(id+" · position & size",b,()->{c.x=value(x,0,100)/100;c.y=value(y,0,100)/100;c.w=value(w,2.5f,50)/100;c.h=value(h,4,70)/100;commit(copy);});}
        else if(section==1){EditText hit=number(b,"Overall touch multiplier (1–2)",c.hitbox),w=number(b,"Touch width multiplier (0.5–3)",c.hitWidth),h=number(b,"Touch height multiplier (0.5–3)",c.hitHeight);form(id+" · touch area",b,()->{c.hitbox=value(hit,1,2);c.hitWidth=value(w,.5f,3);c.hitHeight=value(h,.5f,3);commit(copy);});}
        else if(section==2){Switch visible=toggle(b,"Visible",c.visible),haptic=toggle(b,"Touch feedback",c.haptic);EditText opacity=number(b,"Opacity (0.1–1)",c.opacity);form(id+" · appearance",b,()->{c.haptic=haptic.isChecked();c.visible=visible.isChecked();c.opacity=value(opacity,.1f,1);commit(copy);});}
